		print("PILOT_READY " + scene_id + " targets=" + str(targets.size()))

func reset(seed_value: int = 20260923) -> void:
	seed(seed_value)
	elapsed = 0.0
	frame = 0
	event_log.clear()
	last_event = "none"
	camera.transform = initial_camera_transform
