{"path":"effect/receiver.gd","content":"extends RefCounted
var faces: Array = []
var textures: Dictionary = {}
func collect(root: Node) -> void:
    faces.clear()
    for node in root.find_children("*", "MeshInstance3D", true, false):
        if not node.is_visible_in_tree() or node.mesh == null:
            continue
        for surface in node.mesh.get_surface_count():
            var arrays = node.mesh.surface_get_arrays(surface)
            var vertices = arrays[Mesh.ARRAY_VERTEX]
            var normals = arrays[Mesh.ARRAY_NORMAL]
            var uvs = arrays[Mesh.ARRAY_TEX_UV]
            var indices = arrays[Mesh.ARRAY_INDEX]
            var material = node.get_active_material(surface)
            var count: int = indices.size() if indices != null and indices.size() > 0 else vertices.size()
            var normal_basis: Basis = node.global_basis.inverse().transposed()
            for t in range(0, count, 3):
                var ps: Array = []
                var ns: Array = []
                var ts: Array = []
                for k in 3:
                    var i: int = indices[t+k] if indices != null and indices.size() > 0 else t+k
                    ps.append(node.global_transform * vertices[i])
                    ns.append((normal_basis * normals[i]).normalized() if normals != null and normals.size() > 0 else Vector3.ZERO)
                    ts.append(uvs[i] if uvs != null and uvs.size() > 0 else Vector2.ZERO)
                faces.append({"p": ps, "n": ns, "uv": ts, "material": material, "node": node})
    print("RECEIVER triangles=", faces.size())

func trace(origin: Vector3, direction: Vector3, only: Node = null) -> Dictionary:
    var distance := INF
    var result: Dictionary = {}
    for face in faces:
        if only != null and not only.is_ancestor_of(face.node) and only != face.node:
            continue
        var a: Vector3 = face.p[0]
        var e1: Vector3 = face.p[1] - a
        var e2: Vector3 = face.p[2] - a
        var h := direction.cross(e2)
        var det := e1.dot(h)
        if absf(det) < 0.0000001:
            continue
        var s := origin - a
        var u := s.dot(h) / det
        if u < -0.000001 or u > 1.000001:
            continue
        var q := s.cross(e1)
        var w := direction.dot(q) / det
        if w < -0.000001 or u+w > 1.000001:
            continue
        var d := e2.dot(q) / det
        if d <= 0.0 or d >= distance:
            continue
        distance = d
        var normal: Vector3 = (face.n[0]*(1.0-u-w) + face.n[1]*u + face.n[2]*w).normalized()
        if normal.length_squared() < 0.1:
            normal = e1.cross(e2).normalized()
        result = {"position": origin + direction*d, "normal": normal, "uv": face.uv[0]*(1.0-u-w)+face.uv[1]*u+face.uv[2]*w, "material": face.material, "node": face.node, "distance": d}
    return result

func color_at(hit: Dictionary) -> Vector3:
    var mat = hit.material
    if not mat is StandardMaterial3D:
        return Vector3.ONE
    var color: Color = mat.albedo_color.srgb_to_linear()
    if mat.albedo_texture != null:
        var id: int = mat.albedo_texture.get_instance_id()
        if not textures.has(id):
            var image: Image = mat.albedo_texture.get_image()
            if image.is_compressed():
                image.decompress()
            textures[id] = image
        var image: Image = textures[id]
        var uv: Vector2 = hit.uv * Vector2(mat.uv1_scale.x,mat.uv1_scale.y) + Vector2(mat.uv1_offset.x,mat.uv1_offset.y)
        var x := posmod(int(floor(uv.x*image.get_width())), image.get_width())
        var y := posmod(int(floor(uv.y*image.get_height())), image.get_height())
        color *= image.get_pixel(x,y).srgb_to_linear()
    return Vector3(color.r,color.g,color.b)
"}

{"path":"effect/sampling.gd","content":"extends RefCounted
static func arr(p: Vector3) -> Array:
    return [p.x,p.y,p.z]

static func capture(effect: Node) -> Dictionary:
    var camera: Camera3D = effect.get_viewport().get_camera_3d()
    var size: Vector2 = effect.get_viewport().get_visible_rect().size
    var pixels: Array = []
    var inv: Transform3D = effect.projector.affine_inverse()
    var settings: Dictionary = effect.test_input.projector
    var ink := Vector3(settings.albedo_linear[0],settings.albedo_linear[1],settings.albedo_linear[2])
    var affected := 0
    var visible := 0
    for y in 128:
        for x in 128:
            var screen := Vector2((x+0.5)/128.0, (y+0.5)/128.0)*size
            var origin := camera.project_ray_origin(screen)
            var direction := camera.project_ray_normal(screen)
            var hit: Dictionary = effect.receiver.trace(origin,direction)
            var row := {"visible":false,"world_position":null,"projector_local_position":null,"uv":null,"opacity":0.0,"normal":null,"albedo_linear":null}
            if not hit.is_empty():
                var world: Vector3 = hit.position
                var view: Vector3 = camera.global_transform.affine_inverse()*world
                var distance := -view.z
                if distance >= camera.near and distance <= camera.far:
                    # Analytical raster-equivalent reverse-Z depth, reconstructed via
                    # the inverse camera projection. CPU reference avoids GPU stalls.
                    var projection := camera.get_camera_projection()
                    var clip: Vector4 = projection * Vector4(view.x,view.y,view.z,1.0)
                    var depth := (clip.z/clip.w)*0.5+0.5
                    var reverse_depth := 1.0-depth
                    var reconstructed: Vector4 = projection.inverse()*Vector4(clip.x/clip.w,clip.y/clip.w, (1.0-reverse_depth)*2.0-1.0,1.0)
                    world = camera.global_transform*(Vector3(reconstructed.x,reconstructed.y,reconstructed.z)/reconstructed.w)
                    var local: Vector3 = inv*world
                    var normal: Vector3 = hit.normal
                    var opacity := 0.0
                    if effect.active and effect.target.is_ancestor_of(hit.node) and absf(local.x)<=0.5 and absf(local.y)<=0.5 and absf(local.z)<=0.5:
                        var cosine := normal.dot(effect.projector.basis.z.normalized())
                        var t := clampf((cosine-float(settings.cos_reject))/(float(settings.cos_full)-float(settings.cos_reject)),0.0,1.0)
                        opacity = float(settings.opacity)*t*t*(3.0-2.0*t)
                    var base: Vector3 = effect.receiver.color_at(hit)
                    var color := base.lerp(ink,opacity)
                    row = {"visible":true,"world_position":arr(world),"projector_local_position":arr(local),"uv":[local.x+0.5,local.y+0.5],"opacity":opacity,"normal":arr(normal),"albedo_linear":arr(color)}
                    visible += 1
                    if opacity > 0.0:
                        affected += 1
            pixels.append(row)
    print("PIXELS step=",effect.frame," visible=",visible," affected=",affected," active=",effect.active)
    return {"step":effect.frame,"elapsed_s":effect.elapsed,"active_target":effect.test_input.hit.target if effect.active else null,"pixel_data":pixels}
"}

