func distance_to_geometry(node: Node3D, origin: Vector3) -> float:
	var distance := INF
	var meshes: Array[Node] = node.find_children("*", "GeometryInstance3D", true, false)
	if node is GeometryInstance3D:
		meshes.append(node)
	for mesh in meshes:
